    /**
     * Tests getting all SalesOrders.
     *
     * @return    Collection
     */
    public List<SalesOrder> testGetAll() throws Throwable {
    LOGGER.info( "SalesOrderTest:testGetAll() - Retrieving Collection of SalesOrders:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all SalesOrder : " );
    List<SalesOrder> collection  = null;

    try {
        // call the static get method on the SalesOrderService
        collection = service.getAllSalesOrder();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            SalesOrder currEntity  = null;
            Iterator<SalesOrder> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getSalesOrderId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

